class Account:
    count = 0
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance
        Account.count = Account.count + 1
    def deposit(self, amount):
        if amount <= 0:
            return False
        else:
            self.balance = self.balance + amount
            return self.balance
    def withdraw(self, amount):
        if amount <= 0:
            return False
        if amount > self.balance:
            return False
        else:
            self.balance = self.balance - amount
            return self.balance
    def describe(self):
        my_str = self.owner + ': Rs ' + str(self.balance)
        return my_str

wallet = Account("Omar", 1000)
print(wallet.describe())

